<section class="request-detail-layout" id="request-information"><div class="stack request-detail-summary"><div class="panel"><h2>Detalles de la solicitud</h2><?php if ($selected['description']): ?><p><?=nl2br(h($selected['description']))?></p><?php endif; ?><p><span class="pill <?=h($selected['status'])?>"><?=h($statusLabels[$selected['status']])?></span> · Prioridad: <?=h($priorityLabels[$selected['priority']])?> · Fecha límite: <?=h($selected['due_date']??'Sin fecha')?></p><p class="muted">Asignado a: <?=h($selected['assigned_name']??'Sin asignar')?></p>
<?php if (in_array($role,['admin','auditor'],true)): ?><div class="request-tools"><?php endif; ?>
<?php if(in_array($selected['status'],['open','submitted','returned'],true) && in_array($role,['auditor','admin'],true)):?>
<details class="request-review" <?php if ($error && $postAction==='status'): ?>open<?php endif; ?>><summary class="action-trigger"><span aria-hidden="true"><?=$selected['status']==='submitted'?'✓':'⊘'?></span> <?=$selected['status']==='submitted'?'Revisar entrega':'Cancelar solicitud'?></summary><form method="post" data-confirm="¿Registrar revisión de esta solicitud?"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="status"><input type="hidden" name="request_id" value="<?=$selected['id']?>"><div class="field"><label>Motivo (obligatorio al devolver o cancelar)<textarea name="reason" maxlength="5000"></textarea></label></div><div class="actions"><?php if ($selected['status']==='submitted'): ?><button name="status" value="accepted">Aceptar</button><button class="secondary" name="status" value="returned">Devolver</button><?php endif; ?><button class="secondary" name="status" value="cancelled">Cancelar solicitud</button></div></form></details><?php endif;?>
<?php if (in_array($role,['admin','auditor'],true)): ?><details class="request-edit" <?php if ($error && $postAction==='edit_request'): ?>open<?php endif; ?>><summary class="action-trigger"><span aria-hidden="true">✎</span> Editar solicitud</summary><?php require dirname(__DIR__).'/app/request-form.php'; ?></details></div><?php endif; ?></div></div><div class="panel request-documents" id="documents"><h2>Documentos compartidos</h2><?php if (in_array($selected['status'],['accepted','cancelled'],true)): ?><p class="muted"><?=$selected['status']==='accepted'?'Esta solicitud fue aceptada.':'Esta solicitud fue cancelada.'?></p><?php else: ?><form method="post" enctype="multipart/form-data" class="request-upload"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="upload"><input type="hidden" name="request_id" value="<?=$selected['id']?>"><div class="field"><label for="document">Selecciona hasta 10 archivos. PDF, Office, imágenes, ZIP, TXT o CSV.</label><input id="document" name="document[]" type="file" multiple required accept=".pdf,.png,.jpg,.jpeg,.txt,.csv,.docx,.xlsx,.zip" data-max-bytes="<?=(int)$config['max_upload_bytes']?>"><p class="small muted">Máximo <?=number_format($config['max_upload_bytes']/1048576,0)?> MB por archivo. El servidor también limita el tamaño total.</p><output id="upload-summary" class="small" aria-live="polite"></output></div><button>Enviar archivos</button></form><?php endif; ?>
<?php foreach($documents as $d):?><div class="file"><div><strong><?=h($d['original_name'])?></strong><div class="small muted">Versión <?=$d['version']?> · <?=h($d['author_name'])?> · <?=h($d['created_at'])?> · <?=number_format((int)$d['byte_size']/1024,1)?> KB</div></div><a href="?action=download&amp;file=<?=$d['id']?>">Descargar</a></div><?php endforeach;?>
<?php if(!$documents):?><p class="muted small document-empty">No hay documentos compartidos todavía.</p><?php endif;?></div></section>
<section class="panel" id="comments"><h2>Comentarios</h2><?php foreach($comments as $c):?><div class="file"><div><strong><?=h($c['author_name'])?></strong> <span class="small muted"><?=h($c['created_at'])?></span><p><?=nl2br(h($c['body']))?></p></div></div><?php endforeach;?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="action" value="comment"><input type="hidden" name="request_id" value="<?=$selected['id']?>"><div class="field"><label for="body">Nuevo comentario</label><textarea id="body" name="body" maxlength="5000" required></textarea></div><button>Publicar comentario</button></form></section><section class="panel" id="request-history"><h2>Actividad reciente</h2><?php foreach($events as $e):?><p class="small"><b><?=h($e['author_name'])?></b> · <?=h($e['action'])?><br><span class="muted"><?=h($e['created_at'])?> <?=h($e['details'])?></span></p><?php endforeach;?></section>
